import re

_PHONE_PATTERN = re.compile(r'(?<!\d)(0\d{1,2})-?(\d{4})-?(\d{4})(?!\d)')

def mask_phone(text):
    return _PHONE_PATTERN.sub(lambda m: f"{m.group(1)}-****-{m.group(3)}", text)

